using UnityEngine;using UnityEditor;using System.Linq;using System.IO;using System.Collections.Generic;
public static class R16PartProbe{
 [MenuItem("Tools/RedCliffs/CaoCao Full Rework/Probe Visible Parts")] public static void Capture(){Main();} public static object Main(){var v=Object.FindObjectsByType<Transform>(FindObjectsInactive.Include).First(t=>t.name=="CaoCao"&&t.Find("VarcoVisual")).Find("VarcoVisual");var model=v.Find("Model");var source=model.GetComponent<Renderer>();var probe=new GameObject("R16 temporary part probe"){hideFlags=HideFlags.HideAndDontSave,layer=31};probe.transform.SetParent(model.parent,false);probe.transform.localPosition=model.localPosition;probe.transform.localRotation=model.localRotation;probe.transform.localScale=model.localScale;probe.AddComponent<MeshFilter>().sharedMesh=model.GetComponent<MeshFilter>().sharedMesh;var rr=probe.AddComponent<MeshRenderer>();var mats=new List<Material>();var cameraObject=new GameObject("R16 temporary probe camera"){hideFlags=HideFlags.HideAndDontSave};var rt=new RenderTexture(1024,1024,24);Texture2D image=null;var old=RenderTexture.active;
 try{foreach(var original in source.sharedMaterials){var m=new Material(Shader.Find("Universal Render Pipeline/Unlit"));m.SetColor("_BaseColor",original.name=="Face"?Color.yellow:original.name=="Body"?Color.green:original.name=="OriginalHair"?Color.red:original.name=="DetailGroom"?Color.cyan:Color.blue);m.SetFloat("_Cull",0);mats.Add(m);}rr.sharedMaterials=mats.ToArray();var c=cameraObject.AddComponent<Camera>();c.enabled=false;c.cullingMask=1<<31;c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=Color.black;c.targetTexture=rt;c.fieldOfView=32;c.nearClipPlane=.02f;var target=v.TransformPoint(new Vector3(0,1.59f,0));c.transform.position=target+v.TransformDirection(new Vector3(0,.01f,-.60f));c.transform.LookAt(target);c.Render();RenderTexture.active=rt;image=new Texture2D(1024,1024,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1024,1024),0,0);image.Apply();File.WriteAllBytes("LocalArchive/CaoCaoHairEnemies20261016/Revision16/part-probe.png",image.EncodeToPNG());return new{Face="yellow",Body="green",OriginalHair="red",DetailGroom="cyan"};}
 finally{RenderTexture.active=old;if(image)Object.DestroyImmediate(image);foreach(var m in mats)Object.DestroyImmediate(m);Object.DestroyImmediate(probe);Object.DestroyImmediate(cameraObject);rt.Release();Object.DestroyImmediate(rt);}}

 [MenuItem("Tools/RedCliffs/CaoCao Full Rework/Probe Temple Material")] public static void Temple(){
 var v=Object.FindObjectsByType<Transform>(FindObjectsInactive.Include).First(t=>t.name=="CaoCao"&&t.Find("VarcoVisual")).Find("VarcoVisual");var model=v.Find("Model");var mesh=model.GetComponent<MeshFilter>().sharedMesh;var mats=model.GetComponent<Renderer>().sharedMaterials;var vertices=mesh.vertices;var uv=mesh.uv;var result=new List<string>();
 for(int k=0;k<mats.Length;k++){if(mats[k].name!="Body")continue;var mat=mats[k];var texture=mat.GetTexture("_BaseMap");var metal=mat.GetTexture("_MetallicGlossMap");var rt=RenderTexture.GetTemporary(texture.width,texture.height,0,RenderTextureFormat.ARGB32,RenderTextureReadWrite.Linear);var old=RenderTexture.active;Graphics.Blit(texture,rt);RenderTexture.active=rt;var copy=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false,true);copy.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);copy.Apply();RenderTexture.active=old;RenderTexture.ReleaseTemporary(rt);result.Add("Material="+mat.name+" Base="+AssetDatabase.GetAssetPath(texture)+" Metal="+AssetDatabase.GetAssetPath(metal));
 foreach(var i in mesh.GetIndices(k).Distinct()){var q=v.InverseTransformPoint(model.TransformPoint(vertices[i]));if(Mathf.Abs(q.x)>.073f&&Mathf.Abs(q.x)<.09f&&q.y>1.60f&&q.y<1.64f)result.Add(q+" uv="+uv[i]+" color="+copy.GetPixelBilinear(uv[i].x,uv[i].y));if(result.Count>25)break;}Object.DestroyImmediate(copy);}
 File.WriteAllLines("LocalArchive/CaoCaoHairEnemies20261016/Revision16/unity-temple-sample.txt",result);
 }
